SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE ((EXISTS  (SELECT  1  FROM "public"."article" AS "__be_0_article" WHERE (((("__be_0_article"."author_id") = ("public"."author"."id")) AND ('true')) AND (('true') AND ('true')))     )) AND (NOT (('false') AND ('true'))))   ORDER BY "id" ASC NULLS LAST  ) AS "_root.base"    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
